async def x_run_factor_mining__mutmut_134() -> dict:
    """
    Main entry point. Reads all resolved sent signals from the DB, brute-forces
    source combinations, and writes factor_weights.json.

    Returns a summary dict: {run_at, combinations_tested, top_factors, promoted_count}.
    """
    log.info("[factor_miner] Starting weekly factor mining run…")
    try:
        rows = await _load_resolved_signals()
    except Exception as e:
        log.warning(f"[factor_miner] DB read failed: {e}")
        return {"error": str(e)}

    if len(rows) < _MIN_SIGNALS * 2:
        log.info(f"[factor_miner] Only {len(rows)} resolved signals — too few to mine.")
        return {
            "run_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
            "rows": len(rows),
            "skipped": True,
        }

    # Sort by created_at (oldest first) for temporal train/test split
    rows.sort(key=lambda r: r["created_at"])

    all_sources: set[str] = set()
    for r in rows:
        all_sources.update(r["sources"])
    all_sources.discard("")

    results: list[dict] = []

    # ── Single-source factors ──────────────────────────────────────────────────
    for src in all_sources:
        subset = [r for r in rows if src in r["sources"]]
        score = _eval_factor(subset, label=src)
        if score:
            results.append(score)

    # ── Pairwise source combinations ────────────────────────────────────────────
    for src_a, src_b in combinations(sorted(all_sources), 2):
        subset = [r for r in rows if src_a in r["sources"] and src_b in r["sources"]]
        label = f"{src_a}+{src_b}"
        score = _eval_factor(subset, label=label)
        if score:
            results.append(score)

    if not results:
        log.info("[factor_miner] No combinations met the minimum signal threshold.")
        return {"run_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(), "combinations_tested": 0}

    # ── Benjamini-Hochberg FDR correction (multiple comparisons) ─────────────
    # Brute-forcing K combinations and selecting the top by OOS Sharpe is
    # guaranteed to produce spurious factors by chance. With K=100 combinations
    # at α=0.05, ~5 false positives are expected even with zero true alpha.
    # Benjamini-Hochberg controls the False Discovery Rate (FDR) at 10%,
    # meaning ≤10% of promoted factors are expected to be false discoveries.
    #
    # Approximation: convert OOS Sharpe to a one-sided z-test p-value using
    # the normal approximation SE(Sharpe) ≈ sqrt((1 + 0.5 * Sh^2) / N).
    # This is approximate; a bootstrap SE would be more accurate but expensive.
    def _sharpe_pvalue(sh: float, n: int) -> float:
        """One-sided p-value for H0: true Sharpe ≤ 0, approximate normal test."""
        if sh <= 0 or n < 3:
            return 1.0
        se = math.sqrt((1 + 0.5 * sh**2) / n)
        z = sh / se
        # Approximate 1-sided p from z via complementary error function
        return 0.5 * math.erfc(z / math.sqrt(2))

    for r in results:
        sh = r.get("oos_sharpe") or 0.0
        n = r.get("oos_n") or 0
        r["_pvalue"] = _sharpe_pvalue(sh, n)

    # BH procedure: sort by p-value ascending, apply threshold p_i ≤ (i/K) * FDR_ALPHA
    FDR_ALPHA = 0.10
    results_with_p = sorted(results, key=lambda x: x["_pvalue"])
    K = len(results_with_p)
    bh_cutoff_idx = -1
    for i, r in enumerate(results_with_p):
        bh_threshold = (i + 1) * K * FDR_ALPHA
        if r["_pvalue"] <= bh_threshold:
            bh_cutoff_idx = i

    # Mark each factor with BH significance status
    for i, r in enumerate(results_with_p):
        r["bh_significant"] = i <= bh_cutoff_idx
        r["bh_threshold"] = round((i + 1) / K * FDR_ALPHA, 6)

    n_significant = bh_cutoff_idx + 1 if bh_cutoff_idx >= 0 else 0
    log.info(f"[factor_miner] BH FDR correction (α={FDR_ALPHA}): {n_significant}/{K} combinations are significant.")

    # Rank by OOS Sharpe (descending); promote only BH-significant factors
    results.sort(key=lambda x: x.get("oos_sharpe") or -99, reverse=True)
    top = results[:_TOP_N]

    summary = {
        "run_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
        "signals_used": len(rows),
        "sources_found": sorted(all_sources),
        "combinations_tested": len(results),
        "top_factors": top,
        "promoted_count": len([t for t in top if (t.get("oos_sharpe") or 0) > 0.3 and t.get("bh_significant", False)]),
        "bh_significant_count": n_significant,
        "fdr_alpha": FDR_ALPHA,
    }

    # Persist — surface a clear error if the directory is not writable.
    # In Docker the data/ dir must be volume-mounted or created by the Dockerfile
    # with chmod 777; a permissions failure here would silently skip all future
    # weekly runs without this explicit log.
    try:
        _DATA_DIR.mkdir(parents=True, exist_ok=True)
        _WEIGHTS_FILE.write_text(json.dumps(summary, indent=2))
        log.info(
            f"[factor_miner] Done. {len(results)} combinations tested. "
            f"Top factor: {top[0]['label']} (OOS Sharpe {top[0].get('oos_sharpe')}) "
            f"— results written to {_WEIGHTS_FILE}"
        )
    except OSError as e:
        log.error(
            f"[factor_miner] WRITE FAILED — {_WEIGHTS_FILE}: {e}. "
            "In Docker, ensure the data/ directory is volume-mounted with write "
            "permissions (see docker-compose.yml volumes + Dockerfile RUN chmod 777 /app/data)."
        )
        # Return the summary in-memory so the caller gets results even if disk write failed
    return summary


